const input = $input.first().json || {};
const body = input.body || input || {};
const params = body.parameters || {};

function splitMulti(value) {
  if (Array.isArray(value)) {
    return value
      .flatMap(v => splitMulti(v))
      .map(v => String(v).trim())
      .filter(Boolean);
  }

  return String(value || "")
    .split(/[\n,; ]+/)
    .map(v => v.trim())
    .filter(Boolean);
}

function safeServerName(ip, index = 0) {
  return `target_${String(ip || `unknown_${index + 1}`).replace(/[^A-Za-z0-9]/g, "_")}`;
}

const ips = splitMulti(
  params.target_ips ||
  params.target_ip ||
  body.target_ips ||
  body.target_ip ||
  body.target
);

const users = splitMulti(
  params.ssh_users ||
  params.ssh_user ||
  body.ssh_users ||
  body.ssh_user ||
  body.sshUser ||
  body.username
);

const sshPort = Number(
  params.ssh_port ||
  params.sshPort ||
  body.ssh_port ||
  body.sshPort ||
  22
);

const scanJobId =
  body.scanJobId ||
  body.scan_job_id ||
  input.scanJobId ||
  null;

if (!ips.length) {
  throw new Error("No target IP found. Please provide parameters.target_ip or parameters.target_ips.");
}

if (!users.length) {
  throw new Error("No SSH user found. Please provide parameters.ssh_user or parameters.ssh_users.");
}

const targets = ips.map((ip, index) => {
  const sshUser = users.length === 1 ? users[0] : users[index];

  if (!sshUser) {
    throw new Error(`No SSH user for target ${ip}. Use one ssh_user for all targets or provide ssh_users with the same count as target_ips.`);
  }

  const serverLabel = safeServerName(ip, index);

  return {
    ip,
    target: ip,
    serverLabel,
    serverName: serverLabel,
    sshUser,
    username: sshUser,
    sshPort,
    sshKeyPath: null,
    legacySsh: false,
    scanJobId
  };
});

return [
  {
    json: {
      toolName: "vuls",
      scanJobId,
      target: targets.length === 1 ? targets[0].ip : "multiple",
      target_ip: targets.length === 1 ? targets[0].ip : targets.map(t => t.ip).join(","),
      sshUser: targets.length === 1 ? targets[0].sshUser : users.join(","),
      sshPort,
      targets
    }
  }
];

const input = $input.first().json || {};

const webhookBody = $("Webhook6").first().json.body || {};
const prepared = $("Prepare Vuls Payload3").first().json || {};

const stdout = input.stdout || "";
const stderr = input.stderr || "";
let rawText = `${stdout}\n${stderr}`;

function safeText(value, fallback = "", maxLength = 1500) {
  return String(value ?? fallback).slice(0, maxLength);
}

function toNumber(value) {
  if (value === null || value === undefined || value === "") return null;
  const n = Number(value);
  return Number.isNaN(n) ? null : n;
}

function normalizeStatus(value) {
  const status = String(value || "OPEN").toUpperCase();

  if (["OPEN", "FAILED", "IGNORED", "CLOSED", "RESOLVED"].includes(status)) {
    return status;
  }

  return "OPEN";
}

function severityFromNvdCvss(score) {
  const n = toNumber(score);

  if (n === null) return "INFO";
  if (n >= 9.0) return "CRITICAL";
  if (n >= 7.0) return "HIGH";
  if (n >= 4.0) return "MEDIUM";
  if (n > 0.0) return "LOW";

  return "INFO";
}

function normalizeSeverity(value, cvss = null) {
  // ถ้ามี CVSS ให้ใช้ NVD CVSS score เป็นหลักเสมอ
  const n = toNumber(cvss);
  if (n !== null) {
    return severityFromNvdCvss(n);
  }

  // fallback กรณีไม่มี score จริง ๆ
  const sev = String(value || "").toUpperCase().trim();

  if (sev === "CRITICAL") return "CRITICAL";
  if (sev === "HIGH" || sev === "IMPORTANT") return "HIGH";
  if (sev === "MEDIUM" || sev === "MODERATE") return "MEDIUM";
  if (sev === "LOW" || sev === "NEGLIGIBLE") return "LOW";

  return "INFO";
}

function extractNvdCvss(finding) {
  if (!finding || typeof finding !== "object") return null;

  // กรณี Execute Command ส่ง cvss มาแล้ว
  const direct = toNumber(finding.cvss);
  if (direct !== null && direct > 0) return direct;

  // กรณีมี nvd อยู่ตรง ๆ
  const nvd =
    finding.nvd ||
    finding.nvd_api ||
    finding.nvdApi ||
    finding.cveContents?.nvd ||
    finding.cveContents?.nvd_api ||
    finding.cveContents?.nvdApi ||
    null;

  function readScore(obj) {
    if (!obj || typeof obj !== "object") return null;

    const keys = [
      "cvss3Score",
      "cvss2Score",
      "cvssScore",
      "baseScore",
      "base_score",
      "score"
    ];

    for (const key of keys) {
      const n = toNumber(obj[key]);
      if (n !== null && n >= 0 && n <= 10) return n;
    }

    // กรณี NVD CVSS v3 อยู่ใน metrics
    const metrics = obj.metrics;
    if (metrics && typeof metrics === "object") {
      const paths = [
        metrics.cvssMetricV31,
        metrics.cvssMetricV30,
        metrics.cvssMetricV2
      ];

      for (const arr of paths) {
        if (Array.isArray(arr)) {
          for (const item of arr) {
            const n =
              toNumber(item?.cvssData?.baseScore) ??
              toNumber(item?.baseScore);
            if (n !== null && n >= 0 && n <= 10) return n;
          }
        }
      }
    }

    return null;
  }

  const fromNvd = readScore(nvd);
  if (fromNvd !== null) return fromNvd;

  // fallback เผื่อ Execute Command ใส่ raw CVE object มาใน finding.raw
  const raw = finding.raw || finding.cve || finding.source || null;
  const fromRaw = readScore(raw);
  if (fromRaw !== null) return fromRaw;

  return null;
}

function extractJsonBlock(text) {
  const startMarker = "###VULS_JSON_START###";
  const endMarker = "###VULS_JSON_END###";

  const start = text.indexOf(startMarker);
  const end = text.indexOf(endMarker);

  if (start === -1 || end === -1 || end <= start) {
    return null;
  }

  const jsonText = text.slice(start + startMarker.length, end).trim();

  try {
    return JSON.parse(jsonText);
  } catch (error) {
    return {
      toolName: "vuls",
      target: prepared.target || webhookBody.target || "N/A",
      status: "failed",
      targets: prepared.targets || [],
      hosts: [],
      findings: [
        {
          title: "VULS JSON Parsing Error",
          severity: "INFO",
          description: `Vuls JSON block could not be parsed: ${error.message}`,
          remediation: "Check the Execute Command output between VULS JSON markers.",
          target: prepared.target || webhookBody.target || "N/A",
          status: "OPEN",
          cvss: 0,
          tool: "vuls"
        }
      ],
      meta: {
        exitCode: input.code ?? null,
        stdoutTail: stdout.slice(-3000),
        stderrTail: stderr.slice(-2000)
      }
    };
  }
}

function splitMulti(value) {
  if (Array.isArray(value)) {
    return value.flatMap(v => splitMulti(v));
  }

  return String(value || "")
    .split(/[\n,;]+/)
    .map(v => v.trim())
    .filter(Boolean);
}

function safeServerName(ip, index = 0) {
  return `target_${String(ip || `unknown_${index + 1}`).replace(/[^A-Za-z0-9]/g, "_")}`;
}

function fallbackTargets() {
  if (Array.isArray(prepared.targets) && prepared.targets.length > 0) {
    return prepared.targets;
  }

  const params = webhookBody.parameters || {};

  const ips = splitMulti(
    params.target_ips ||
    params.target_ip ||
    prepared.target ||
    webhookBody.target
  );

  const users = splitMulti(
    params.ssh_users ||
    params.ssh_user ||
    prepared.sshUser ||
    prepared.username
  );

  const sshPort = Number(params.ssh_port || prepared.sshPort || 22);

  return ips.map((ip, index) => ({
    ip,
    target: ip,
    serverLabel: safeServerName(ip, index),
    serverName: safeServerName(ip, index),
    sshUser: users.length === 1 ? users[0] : users[index] || null,
    username: users.length === 1 ? users[0] : users[index] || null,
    sshPort
  }));
}

function normalizeFinding(finding, defaultTarget) {
  const nvdCvss = extractNvdCvss(finding);
const cvss = nvdCvss ?? toNumber(finding.cvss) ?? 0;
const severity = severityFromNvdCvss(cvss);

  return {
    title: safeText(finding.title, "Unknown Finding", 200),
    severity,
    description: safeText(
      finding.description,
      "Vuls detected a vulnerability on the target host.",
      1500
    ),
    remediation: safeText(
      finding.remediation,
      "Review affected packages and apply vendor security updates.",
      1000
    ),
    target: safeText(finding.target, defaultTarget, 200),
    serverName: finding.serverName || finding.serverLabel || null,
    serverLabel: finding.serverLabel || finding.serverName || null,
    status: normalizeStatus(finding.status),
    cvss,
    tool: "vuls"
  };
}

function parseVulsOneLineSummaryByHost(text) {
  const results = [];
  const cleaned = String(text || "").replace(/\x1b\[[0-9;]*m/g, "");
  const lines = cleaned.split(/\r?\n/);

  for (const line of lines) {
    const m = line.match(
      /(?:^|\s)([A-Za-z0-9_.-]+)\s+Total:\s*(\d+)\s*\(\s*(?:Critical:\s*(\d+)\s+)?High:\s*(\d+)\s+Medium:\s*(\d+)\s+Low:\s*(\d+)\s+\?:\s*(\d+)\s*\)/
    );

    if (!m) continue;

    results.push({
      serverName: m[1],
      serverLabel: m[1],
      total: Number(m[2]),
      critical: Number(m[3] || 0),
      high: Number(m[4]),
      medium: Number(m[5]),
      low: Number(m[6]),
      info: Number(m[7])
    });
  }

  return results;
}

function buildSummary(findings) {
  return {
    total: findings.length,
    returned: findings.length,
    critical: findings.filter(f => f.severity === "CRITICAL").length,
    high: findings.filter(f => f.severity === "HIGH").length,
    medium: findings.filter(f => f.severity === "MEDIUM").length,
    low: findings.filter(f => f.severity === "LOW").length,
    info: findings.filter(f => f.severity === "INFO").length
  };
}

function makeSeverityMix(summary) {
  return [
    { severity: "CRITICAL", count: summary.critical },
    { severity: "HIGH", count: summary.high },
    { severity: "MEDIUM", count: summary.medium },
    { severity: "LOW", count: summary.low },
    { severity: "INFO", count: summary.info }
  ];
}

function portalStatus(status) {
  const s = String(status || "").toLowerCase();
  if (s === "failed") return "failed";
  return "completed";
}

function dedupeFindings(list) {
  const seen = new Set();
  const out = [];

  for (const f of list) {
    const key = [
      f.serverName || f.serverLabel || "",
      f.target || "",
      f.title || ""
    ].join("|");

    if (seen.has(key)) continue;

    seen.add(key);
    out.push(f);
  }

  return out;
}

function rebalanceFindingSeveritiesByOneLine(findings, oneLineHosts) {
  const output = findings.map(f => ({ ...f }));

  const groups = {};
  for (const f of output) {
    const key = f.serverName || f.serverLabel || "";
    if (!groups[key]) groups[key] = [];
    groups[key].push(f);
  }

  for (const hostSummary of oneLineHosts) {
    let list = groups[hostSummary.serverName] || [];

    if (!list.length) {
      list = output.filter(f =>
        String(f.serverName || "").includes(hostSummary.serverName) ||
        String(f.serverLabel || "").includes(hostSummary.serverName)
      );
    }

    const wanted = [
      ["CRITICAL", hostSummary.critical],
      ["HIGH", hostSummary.high],
      ["MEDIUM", hostSummary.medium],
      ["LOW", hostSummary.low],
      ["INFO", hostSummary.info]
    ];

    let index = 0;

    for (const [severity, count] of wanted) {
      for (let i = 0; i < count && index < list.length; i++) {
        list[index].severity = severity;

        if (severity === "CRITICAL") list[index].cvss = list[index].cvss >= 9 ? list[index].cvss : 9.0;
        if (severity === "HIGH") list[index].cvss = list[index].cvss >= 7 && list[index].cvss < 9 ? list[index].cvss : 7.0;
        if (severity === "MEDIUM") list[index].cvss = list[index].cvss >= 4 && list[index].cvss < 7 ? list[index].cvss : 4.0;
        if (severity === "LOW") list[index].cvss = list[index].cvss > 0 && list[index].cvss < 4 ? list[index].cvss : 0.1;
        if (severity === "INFO") list[index].cvss = list[index].cvss || 0;

        index++;
      }
    }
  }

  return output;
}

function createPlaceholderFindings(findings, oneLineHosts, hosts, targets, defaultTarget) {
  const output = findings.map(f => ({ ...f }));

  const countByServer = {};
  for (const f of output) {
    const server = f.serverName || f.serverLabel || "unknown";
    countByServer[server] = (countByServer[server] || 0) + 1;
  }

  function findTargetForServer(serverName) {
    const host = hosts.find(h =>
      h.serverName === serverName ||
      h.serverLabel === serverName
    );

    if (host?.ip || host?.target) {
      return String(host.ip || host.target);
    }

    const target = targets.find(t =>
      t.serverName === serverName ||
      t.serverLabel === serverName
    );

    if (target?.ip || target?.target) {
      return String(target.ip || target.target);
    }

    return String(defaultTarget || serverName || "N/A");
  }

  for (const host of oneLineHosts) {
    const current = countByServer[host.serverName] || 0;
    const missing = Math.max(0, Number(host.total || 0) - current);
    const realTarget = findTargetForServer(host.serverName);

    const severityPlan = [
      ["CRITICAL", host.critical || 0],
      ["HIGH", host.high || 0],
      ["MEDIUM", host.medium || 0],
      ["LOW", host.low || 0],
      ["INFO", host.info || 0]
    ];

    let created = 0;

    for (const [severity, count] of severityPlan) {
      for (let i = 0; i < count && created < missing; i++) {
        created++;

        const cvss =
          severity === "CRITICAL" ? 9.0 :
          severity === "HIGH" ? 7.0 :
          severity === "MEDIUM" ? 4.0 :
          severity === "LOW" ? 0.1 :
          0;

        output.push({
          title: `VULS Summary Finding ${host.serverName} #${created}`,
          severity,
          description:
            `Vuls one-line summary reported a ${severity} finding for ${realTarget}, but detailed CVE JSON for this item was not parsed.`,
          remediation:
            "Check Vuls JSON report files for this target if exact CVE IDs are required.",
          target: realTarget,
          serverName: host.serverName,
          serverLabel: host.serverName,
          status: "OPEN",
          cvss,
          tool: "vuls"
        });
      }
    }
  }

  return output;
}

let payload = extractJsonBlock(rawText);

if (!payload) {
  const targets = fallbackTargets();
  let oneLineHosts = [];

if (Array.isArray(payload?.meta?.oneLineHosts) && payload.meta.oneLineHosts.length > 0) {
  oneLineHosts = payload.meta.oneLineHosts.map(h => ({
    serverName: h.serverName || h.serverLabel,
    serverLabel: h.serverLabel || h.serverName,
    total: Number(h.total || 0),
    critical: Number(h.critical || 0),
    high: Number(h.high || 0),
    medium: Number(h.medium || 0),
    low: Number(h.low || 0),
    info: Number(h.info || 0)
  }));
} else {
  oneLineHosts = parseVulsOneLineSummaryByHost(rawText);
}

  payload = {
    toolName: "vuls",
    status: oneLineHosts.length ? "completed" : "failed",
    target: targets.length === 1 ? targets[0].ip || targets[0].target : "multiple",
    targets,
    hosts: oneLineHosts.map(h => ({
      ...h,
      serverLabel: h.serverName,
      ip: h.serverName,
      target: h.serverName,
      status: "completed"
    })),
    findings: [],
    meta: {
      tool: "vuls",
      scanJobId: prepared.scanJobId || webhookBody.scanJobId || null,
      exitCode: input.code ?? null,
      stdoutTail: stdout.slice(-3000),
      stderrTail: stderr.slice(-2000),
      note: "JSON marker was not found.",
      oneLineHostsDebug: oneLineHosts,
      oneLineHostsCount: oneLineHosts.length
    }
  };
}

rawText = [
  rawText,
  payload?.meta?.sshPreflightLog || "",
  payload?.meta?.scanLog || "",
  payload?.meta?.reportLog || "",
  payload?.meta?.reportSummaryLog || "",
  payload?.meta?.configtestLog || ""
].join("\n");

const targets = Array.isArray(payload.targets) ? payload.targets : fallbackTargets();
const hosts = Array.isArray(payload.hosts) ? payload.hosts : [];
const defaultTarget =
  payload.target ||
  prepared.target ||
  webhookBody.parameters?.target_ip ||
  webhookBody.target ||
  "N/A";

let findings = Array.isArray(payload.findings) ? payload.findings : [];

if (String(payload.status || "").toLowerCase() === "failed" && findings.length === 0) {
  const meta = payload.meta || {};
  const reason =
    meta.sshPreflightLog ||
    meta.reportLog ||
    meta.scanLog ||
    meta.configtestLog ||
    meta.stderrTail ||
    meta.stdoutTail ||
    "Vuls did not produce any JSON report files.";

  findings = [
    {
      title: "VULS Scan Failed",
      severity: "INFO",
      description: String(reason).slice(-1500),
      remediation: "Check SSH access, key path, Vuls configtest output, and whether Docker/Vuls can reach the target host.",
      target: defaultTarget,
      status: "OPEN",
      cvss: 0,
      tool: "vuls"
    }
  ];
}

findings = findings.map(f => normalizeFinding(f, defaultTarget));
findings = dedupeFindings(findings);

const oneLineHosts = parseVulsOneLineSummaryByHost(rawText);

const oneLineSummary =
  oneLineHosts.length > 0
    ? {
        total: oneLineHosts.reduce((sum, h) => sum + h.total, 0),
        returned: oneLineHosts.reduce((sum, h) => sum + h.total, 0),
        critical: oneLineHosts.reduce((sum, h) => sum + h.critical, 0),
        high: oneLineHosts.reduce((sum, h) => sum + h.high, 0),
        medium: oneLineHosts.reduce((sum, h) => sum + h.medium, 0),
        low: oneLineHosts.reduce((sum, h) => sum + h.low, 0),
        info: oneLineHosts.reduce((sum, h) => sum + h.info, 0)
      }
    : null;

if (oneLineHosts.length > 0) {
  for (const oneLineHost of oneLineHosts) {
    let host = hosts.find(h =>
      h.serverName === oneLineHost.serverName ||
      h.serverLabel === oneLineHost.serverName
    );

    if (!host) {
      host = {
        serverName: oneLineHost.serverName,
        serverLabel: oneLineHost.serverName,
        ip: oneLineHost.serverName,
        target: oneLineHost.serverName
      };
      hosts.push(host);
    }

    host.total = oneLineHost.total;
    host.critical = oneLineHost.critical;
    host.high = oneLineHost.high;
    host.medium = oneLineHost.medium;
    host.low = oneLineHost.low;
    host.info = oneLineHost.info;
    host.status = "completed";
  }
}

if (oneLineSummary && findings.length > oneLineSummary.total) {
  findings = findings.slice(0, oneLineSummary.total);
}

// if (oneLineSummary && findings.length < oneLineSummary.total) {
//   findings = createPlaceholderFindings(
//     findings,
//     oneLineHosts,
//     hosts,
//     targets,
//     defaultTarget
//   );
// }

// if (oneLineSummary && findings.length === oneLineSummary.total) {
//   findings = rebalanceFindingSeveritiesByOneLine(findings, oneLineHosts);
// }

if (oneLineSummary && findings.length > oneLineSummary.total) {
  findings = findings.slice(0, oneLineSummary.total);
}

// ใช้ Vuls One Line Summary เป็น fallback หลัก
// เพื่อให้จำนวนบน portal ตรงกับ Vuls CLI:
// Total / Critical / High / Medium / Low / ?
if (oneLineSummary && findings.length < oneLineSummary.total) {
  findings = createPlaceholderFindings(
    findings,
    oneLineHosts,
    hosts,
    targets,
    defaultTarget
  );
}

// ถ้ามี findings เท่ากับจำนวน summary แล้ว ให้จัด severity ให้ตรงกับ One Line Summary
if (oneLineSummary && findings.length === oneLineSummary.total) {
  findings = rebalanceFindingSeveritiesByOneLine(findings, oneLineHosts);
}

// ถ้าไม่มี One Line Summary และไม่มี CVE JSON จริง ๆ ค่อยให้ว่าง
if (!oneLineSummary && findings.length === 0) {
  findings = [];
}

// const MAX_FINDINGS = 5000;
// if (findings.length > MAX_FINDINGS) {
//   findings = findings.slice(0, MAX_FINDINGS);
// }

const finalSummary = buildSummary(findings);
const finalSeverityMix = makeSeverityMix(finalSummary);

const scanJobId =
  payload.meta?.scanJobId ||
  prepared.scanJobId ||
  webhookBody.scanJobId ||
  null;

const portalPayload = {
  toolName: "vuls",

  target:
    targets.length === 1
      ? String(targets[0].ip || targets[0].target || payload.target || "N/A")
      : "multiple",

  target_ip:
    targets.length === 1
      ? String(targets[0].ip || targets[0].target || "N/A")
      : targets.map(t => String(t.ip || t.target || "")).filter(Boolean).join(","),

  status: portalStatus(payload.status),

  // สำคัญ: ส่ง hosts และ targets ออกไปให้หน้าเว็บใช้ตรง ๆ
  targets: targets.map(t => ({
    ip: t.ip || t.target,
    target: t.target || t.ip,
    serverName: t.serverName || t.serverLabel,
    serverLabel: t.serverLabel || t.serverName,
    sshUser: t.sshUser || t.username,
    username: t.username || t.sshUser,
    sshPort: t.sshPort || 22
  })),

  hosts: hosts.map(h => {
    const matchedTarget = targets.find(t =>
      t.serverName === h.serverName ||
      t.serverLabel === h.serverName ||
      t.serverName === h.serverLabel ||
      t.serverLabel === h.serverLabel
    );

    return {
      serverName: h.serverName || h.serverLabel,
      serverLabel: h.serverLabel || h.serverName,
      ip: h.ip || h.target || matchedTarget?.ip || matchedTarget?.target || h.serverName,
      target: h.target || h.ip || matchedTarget?.target || matchedTarget?.ip || h.serverName,
      sshUser: h.sshUser || h.username || matchedTarget?.sshUser || matchedTarget?.username || null,
      username: h.username || h.sshUser || matchedTarget?.username || matchedTarget?.sshUser || null,
      sshPort: h.sshPort || matchedTarget?.sshPort || 22,
      total: Number(h.total || 0),
      critical: Number(h.critical || 0),
      high: Number(h.high || 0),
      medium: Number(h.medium || 0),
      low: Number(h.low || 0),
      info: Number(h.info || 0),
      status: h.status || "completed"
    };
  }),

  findings: findings.map(f => {
  const matchedTarget = targets.find(t =>
    t.serverName === f.serverName ||
    t.serverLabel === f.serverLabel ||
    t.serverName === f.serverLabel ||
    t.serverLabel === f.serverName ||
    t.ip === f.target ||
    t.target === f.target
  );

  const realIp =
    f.target ||
    matchedTarget?.ip ||
    matchedTarget?.target ||
    "N/A";

  const realServerName =
    f.serverName ||
    f.serverLabel ||
    matchedTarget?.serverName ||
    matchedTarget?.serverLabel ||
    null;

  const realServerLabel =
    f.serverLabel ||
    f.serverName ||
    matchedTarget?.serverLabel ||
    matchedTarget?.serverName ||
    null;

  const nvdCvss = extractNvdCvss(f);
  const realCvss = nvdCvss ?? toNumber(f.cvss) ?? 0;

  return {
    title: String(f.title || "Unknown Finding").slice(0, 200),
    severity: severityFromNvdCvss(realCvss),
    description: String(f.description || "Vuls detected a vulnerability on the target host.").slice(0, 1500),
    remediation: String(f.remediation || "Review affected packages and apply vendor security updates.").slice(0, 1000),

    target: String(realIp).slice(0, 200),
    ip: String(realIp).slice(0, 200),
    serverName: realServerName,
    serverLabel: realServerLabel,

    status: normalizeStatus(f.status),
    cvss: realCvss,
    tool: "vuls"
  };
}),

  summary: finalSummary,

  perHostSummary: hosts.map(h => ({
    serverName: h.serverName || h.serverLabel,
    serverLabel: h.serverLabel || h.serverName,
