const body = $("Webhook6").first().json.body || {};
const params = body.parameters || {};

const targetName =
  params.target_name ||
  params.service_name ||
  params.name ||
  "metlo-target";

const baseUrl =
  params.base_url ||
  params.target_url ||
  body.target ||
  "";

const metloBackendUrl =
  params.metlo_backend_url ||
  "http://host.docker.internal:8080";

if (!baseUrl) {
  throw new Error("Missing base_url for METLO");
}

return [
  {
    json: {
      scanJobId: body.scanJobId,
      toolName: "metlo",
      target: baseUrl,
      targetName,
      metloBackendUrl
    }
  }
];

const payload = $("Prepare Metlo Payload").first().json || {};

const endpointItems = $("get metlo req").all().map(i => i.json || {});
const summaryItems = $("Get Metlo Summary").all().map(i => i.json || {});

// ต้องมี node นี้: Get Security Catalog
let catalogItems = [];
try {
  catalogItems = $("Get Security Catalog").all().map(i => i.json || {});
} catch (e) {
  catalogItems = [];
}

const scanJobId = payload.scanJobId || null;

const fallbackTarget =
  payload.target ||
  payload.baseUrl ||
  payload.url ||
  "N/A";

const targetName = payload.targetName || payload.serviceName || "metlo-target";
const metloBackendUrl = payload.metloBackendUrl || "http://host.docker.internal:8080";

function pickFirst(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && value !== "") return value;
  }
  return undefined;
}

function safeText(value, fallback = "", maxLength = 1500) {
  return String(value ?? fallback).slice(0, maxLength);
}

function asArray(value) {
  if (Array.isArray(value)) return value;
  if (Array.isArray(value?.data)) return value.data;
  if (Array.isArray(value?.items)) return value.items;
  if (Array.isArray(value?.results)) return value.results;
  if (Array.isArray(value?.endpoints)) return value.endpoints;
  if (Array.isArray(value?.routes)) return value.routes;
  if (Array.isArray(value?.catalog)) return value.catalog;
  if (Array.isArray(value?.alerts)) return value.alerts;
  if (Array.isArray(value?.topAlerts)) return value.topAlerts;
  return [];
}

function normalizeSeverity(value) {
  const sev = String(value || "").toUpperCase();

  if (sev === "CRITICAL") return "CRITICAL";
  if (sev === "HIGH") return "HIGH";
  if (sev === "MEDIUM" || sev === "MODERATE") return "MEDIUM";
  if (sev === "LOW") return "LOW";
  if (sev === "INFO" || sev === "INFORMATIONAL" || sev === "NONE") return "INFO";

  return "INFO";
}

function riskToSeverity(value) {
  const risk = String(value || "").toLowerCase();

  if (risk.includes("critical")) return "CRITICAL";
  if (risk.includes("high")) return "HIGH";
  if (risk.includes("medium") || risk.includes("moderate")) return "MEDIUM";
  if (risk.includes("low")) return "LOW";
  if (risk.includes("none")) return "INFO";

  return "INFO";
}

function getMethod(obj) {
  return String(
    obj?.method ||
    obj?.httpMethod ||
    obj?.http_method ||
    obj?.apiEndpoint?.method ||
    "UNKNOWN"
  ).toUpperCase();
}

function getPath(obj) {
  return (
    obj?.path ||
    obj?.route ||
    obj?.url ||
    obj?.endpoint ||
    obj?.apiEndpoint?.path ||
    obj?.apiEndpoint?.url ||
    obj?.apiEndpoint?.endpoint ||
    "Unknown Endpoint"
  );
}

function getHost(obj) {
  return (
    obj?.host ||
    obj?.domain ||
    obj?.apiEndpoint?.host ||
    obj?.apiEndpoint?.domain ||
    ""
  );
}

function normalizeHost(host) {
  let h = String(host || "")
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, "")
    .replace(/\/+$/, "");

  if (h.startsWith("localhost:")) {
    h = h.replace("localhost:", "127.0.0.1:");
  }

  return h;
}

function getTargetHost(targetUrl) {
  try {
    return normalizeHost(new URL(targetUrl).host);
  } catch (e) {
    return normalizeHost(targetUrl);
  }
}

const targetHost = getTargetHost(fallbackTarget);

function isEndpointForTarget(endpoint) {
  const endpointHost = normalizeHost(getHost(endpoint));
  return endpointHost === targetHost;
}

function normalizePathForMatch(path) {
  let p = String(path || "").trim();

  // Flask style: /users/<int:user_id>
  p = p
    .replace(/<int:[^>]+>/g, "{param1}")
    .replace(/<string:[^>]+>/g, "{param1}")
    .replace(/<float:[^>]+>/g, "{param1}")
    .replace(/<path:[^>]+>/g, "{param1}")
    .replace(/<[^>]+>/g, "{param1}");

  // Metlo style อาจมี /users/{param1} อยู่แล้ว
  p = p.replace(/\{[^}]+\}/g, "{param1}");

  // ตัด query string ออก
  p = p.split("?")[0];

  if (!p.startsWith("/")) p = `/${p}`;

  return p;
}

function catalogKey(method, path) {
  return `${String(method || "").toUpperCase()}|${normalizePathForMatch(path)}`;
}

function endpointKey(method, path, host) {
  return `${normalizeHost(host)}|${catalogKey(method, path)}`;
}

function looksLikeEndpoint(obj) {
  return !!(
    obj &&
    typeof obj === "object" &&
    (
      obj.path ||
      obj.route ||
      obj.endpoint ||
      obj.method ||
      obj.uuid ||
      obj.riskScore ||
      obj.firstDetected ||
      obj.lastActive
    )
  );
}

function getCatalogMethod(catalog) {
  return String(
    catalog.method ||
    catalog.httpMethod ||
    catalog.http_method ||
    "GET"
  ).toUpperCase();
}

function getCatalogPath(catalog) {
  return (
    catalog.path ||
    catalog.route ||
    catalog.endpoint ||
    catalog.url ||
    "/"
  );
}

function getCatalogSeverity(catalog) {
  return normalizeSeverity(
    catalog.severity ||
    catalog.riskSeverity ||
    catalog.risk_severity ||
    catalog.level ||
    catalog.security_demo?.severity ||
    "INFO"
  );
}

function getCatalogAuthRequired(catalog) {
  return (
    catalog.authRequired === true ||
    catalog.auth_required === true ||
    catalog.requiresAuth === true ||
    catalog.requires_auth === true ||
    catalog.security_demo?.authRequired === true ||
    catalog.security_demo?.auth_required === true
  );
}

function getCatalogRisk(catalog) {
  return (
    catalog.risk ||
    catalog.riskScore ||
    catalog.risk_score ||
    catalog.security_demo?.risk ||
    catalog.security_demo?.riskScore ||
    ""
  );
}

function getCatalogDescription(catalog) {
  return (
    catalog.description ||
    catalog.summary ||
    catalog.security_demo?.description ||
    catalog.security_demo?.summary ||
    ""
  );
}

function getCatalogRemediation(catalog) {
  return (
    catalog.remediation ||
    catalog.fix ||
    catalog.recommendation ||
    catalog.security_demo?.remediation ||
    "Review endpoint exposure, authentication, authorization, and sensitive data handling."
  );
}

// ------------------------------
// 1) ดึง endpoint ที่ Metlo เคยเห็นจริง
// ------------------------------
const rawEndpoints = [];

for (const item of endpointItems) {
  rawEndpoints.push(...asArray(item));
  rawEndpoints.push(...asArray(item.data));
  rawEndpoints.push(...asArray(item.items));
  rawEndpoints.push(...asArray(item.results));
  rawEndpoints.push(...asArray(item.endpoints));

  if (looksLikeEndpoint(item)) {
    rawEndpoints.push(item);
  }

  if (looksLikeEndpoint(item["0"])) {
    rawEndpoints.push(item["0"]);
  }
}

// ------------------------------
// 2) ดึง alerts จาก summary เอาไว้เสริมข้อมูล
// ------------------------------
const alerts = [];

for (const item of summaryItems) {
  alerts.push(...asArray(item.topAlerts));
  alerts.push(...asArray(item.alerts));
  alerts.push(...asArray(item.data?.topAlerts));
  alerts.push(...asArray(item.data?.alerts));
}

const alertsByEndpoint = new Map();

for (const alert of alerts) {
  const ep = alert.apiEndpoint || alert.endpoint || alert;
  const key = endpointKey(getMethod(ep), getPath(ep), getHost(ep));

  if (!alertsByEndpoint.has(key)) {
    alertsByEndpoint.set(key, []);
  }

  alertsByEndpoint.get(key).push(alert);
}

// ------------------------------
// 3) กรอง endpoint ให้เหลือเฉพาะ target ที่ผู้ใช้กรอก
// ------------------------------
const uniqueEndpoints = [];
const seenObserved = new Set();

for (const endpoint of rawEndpoints) {
  const method = getMethod(endpoint);
  const path = getPath(endpoint);
  const host = getHost(endpoint);

  if (method === "UNKNOWN" && path === "Unknown Endpoint") continue;
  if (!isEndpointForTarget(endpoint)) continue;

  const key = endpoint.uuid || endpointKey(method, path, host);

  if (!seenObserved.has(key)) {
    seenObserved.add(key);
    uniqueEndpoints.push(endpoint);
  }
}

// ------------------------------
// 4) สร้าง map ของ observed endpoint
// ------------------------------
const observedByMethodPath = new Map();

for (const endpoint of uniqueEndpoints) {
  const method = getMethod(endpoint);
  const path = getPath(endpoint);

  observedByMethodPath.set(catalogKey(method, path), endpoint);
}

// ------------------------------
// 5) ดึง catalog endpoint ทั้งหมดจาก Get Security Catalog
// ------------------------------
let catalogEndpoints = [];

for (const item of catalogItems) {
  catalogEndpoints.push(...asArray(item.endpoints));
  catalogEndpoints.push(...asArray(item.routes));
  catalogEndpoints.push(...asArray(item.catalog));
  catalogEndpoints.push(...asArray(item.data));
  catalogEndpoints.push(...asArray(item.items));
  catalogEndpoints.push(...asArray(item.results));

  if (looksLikeEndpoint(item) && (item.severity || item.authRequired !== undefined || item.security_demo)) {
    catalogEndpoints.push(item);
  }
}

// กัน catalog ซ้ำ
const uniqueCatalogEndpoints = [];
const seenCatalog = new Set();

for (const catalog of catalogEndpoints) {
  const method = getCatalogMethod(catalog);
  const path = getCatalogPath(catalog);
  const key = catalogKey(method, path);

  if (!seenCatalog.has(key)) {
    seenCatalog.add(key);
    uniqueCatalogEndpoints.push(catalog);
  }
}

// ------------------------------
// 6) สร้าง findings
// ถ้ามี catalog → ใช้ catalog เป็นหลัก
// ถ้าไม่มี catalog → fallback ใช้ observed endpoints จาก Metlo
// ------------------------------
const findings = [];

if (uniqueCatalogEndpoints.length > 0) {
  for (const catalog of uniqueCatalogEndpoints) {
    const method = getCatalogMethod(catalog);
    const path = getCatalogPath(catalog);
    const normalizedKey = catalogKey(method, path);

    const observed = observedByMethodPath.get(normalizedKey);
    const hasAccess = !!observed;

    const host = observed ? getHost(observed) : targetHost;

    const firstSeen = observed
      ? pickFirst(
          observed.firstDetected,
          observed.createdAt,
          observed.updatedAt
        )
      : null;

    const lastSeen = observed
      ? pickFirst(
          observed.lastActive,
          observed.updatedAt,
          firstSeen
        )
      : null;

    const observedRange =
      firstSeen && lastSeen
        ? `${firstSeen} → ${lastSeen}`
        : (lastSeen || firstSeen || "");

    const severity = getCatalogSeverity(catalog);
    const authRequired = getCatalogAuthRequired(catalog);
    const risk = getCatalogRisk(catalog);
    const catalogDescription = getCatalogDescription(catalog);

    const descriptionParts = [
      hasAccess
        ? "This endpoint exists in the application security catalog and has been observed by Metlo from real application traffic."
        : "This endpoint exists in the application security catalog but has not been observed by Metlo traffic yet.",
      `Endpoint: ${method} ${path}.`,
      `Auth required: ${authRequired ? "yes" : "no"}.`
    ];

    if (risk) descriptionParts.push(`Risk: ${risk}.`);
    if (catalogDescription) descriptionParts.push(`Details: ${catalogDescription}.`);
    if (firstSeen) descriptionParts.push(`First detected: ${firstSeen}.`);
    if (lastSeen) descriptionParts.push(`Last active: ${lastSeen}.`);

    findings.push({
      title: hasAccess
        ? safeText(`API Traffic Observed - ${method} ${path}`, "Metlo API Endpoint", 200)
        : safeText(`API Endpoint Not Accessed Yet - ${method} ${path}`, "Metlo API Endpoint", 200),

      severity,
      description: safeText(descriptionParts.join(" "), "Metlo API endpoint record.", 1500),
      remediation: getCatalogRemediation(catalog),
      target: host || fallbackTarget,
      status: "OPEN",
      cvss: Number(catalog.cvss || catalog.security_demo?.cvss || 0),
      tool: "metlo",

      // ให้ frontend เอา Age จาก lastSeen / ageLabel
      // ถ้ายังไม่เคย access จะไม่ใส่ createdAt เป็นเวลาปัจจุบัน เพราะจะทำให้ขึ้น just now
      createdAt: hasAccess ? (lastSeen || firstSeen) : null,
      firstSeen: firstSeen || null,
      lastSeen: lastSeen || null,
      observedRange,

      ageLabel: hasAccess ? null : "No access yet",
      accessStatus: hasAccess ? "accessed" : "no_access",
      metloObserved: hasAccess,

      authRequired,
      endpointPath: path,
      method
    });
  }
} else {
  // fallback กรณียังไม่มี Get Security Catalog หรือ catalog ว่าง
  for (const endpoint of uniqueEndpoints) {
    const method = getMethod(endpoint);
    const path = getPath(endpoint);
    const host = getHost(endpoint);

    const key = endpointKey(method, path, host);
    const matchedAlerts = alertsByEndpoint.get(key) || [];
    const firstAlert = matchedAlerts[0] || {};

    const risk = pickFirst(
      endpoint.riskScore,
      endpoint.risk,
      endpoint.riskLevel,
      endpoint.risk_level,
      endpoint.severity,
      endpoint.threatLevel,
      endpoint.threat_level,
      firstAlert.riskScore,
      firstAlert.risk,
      firstAlert.riskLevel,
      firstAlert.risk_level,
      firstAlert.severity,
      "none"
    );

    const severity = riskToSeverity(risk);

    const firstSeen = pickFirst(
      endpoint.firstDetected,
      endpoint.createdAt,
      firstAlert.createdAt,
      endpoint.updatedAt
    );

    const lastSeen = pickFirst(
      endpoint.lastActive,
      endpoint.updatedAt,
      firstAlert.createdAt,
      firstSeen
    );

    const observedRange =
      firstSeen && lastSeen
        ? `${firstSeen} → ${lastSeen}`
        : (lastSeen || firstSeen || "");

    findings.push({
      title: safeText(`API Traffic Observed - ${method} ${path}`, "Metlo API Endpoint", 200),
      severity,
      description: safeText(
        [
          "Metlo observed this API endpoint from application traffic.",
          host ? `Host: ${host}.` : "",
          `Endpoint: ${method} ${path}.`,
          risk ? `Risk score: ${risk}.` : "",
          firstSeen ? `First detected: ${firstSeen}.` : "",
          lastSeen ? `Last active: ${lastSeen}.` : ""
        ].filter(Boolean).join(" "),
        "Metlo observed an API endpoint.",
        1500
      ),
      remediation: "Review endpoint exposure, authentication, authorization, and sensitive data handling.",
      target: host || fallbackTarget,
      status: "OPEN",
      cvss: 0,
      tool: "metlo",

      createdAt: lastSeen || firstSeen || null,
      firstSeen: firstSeen || null,
      lastSeen: lastSeen || null,
      observedRange,

      ageLabel: null,
      accessStatus: "accessed",
      metloObserved: true,

      authRequired: endpoint.isAuthenticatedDetected === true,
      endpointPath: path,
      method
    });
  }
}

// ------------------------------
// 7) fallback ถ้าไม่มีอะไรเลย
// ------------------------------
if (findings.length === 0) {
  findings.push({
    title: "METLO Data Retrieved",
    severity: "INFO",
    description: "Metlo data was retrieved, but no observed API endpoints or security catalog entries were parsed.",
    remediation: "Check get metlo req1 output and Get Security Catalog output.",
    target: fallbackTarget,
    status: "OPEN",
    cvss: 0,
    tool: "metlo",
    createdAt: null,
    firstSeen: null,
    lastSeen: null,
    observedRange: "",
    ageLabel: "No access yet",
    accessStatus: "no_access",
    metloObserved: false,
    authRequired: false,
    endpointPath: null,
    method: null
  });
}

function buildSummary(items) {
  return {
    total: items.length,
    returned: items.length,
    critical: items.filter(f => f.severity === "CRITICAL").length,
    high: items.filter(f => f.severity === "HIGH").length,
    medium: items.filter(f => f.severity === "MEDIUM").length,
    low: items.filter(f => f.severity === "LOW").length,
    info: items.filter(f => f.severity === "INFO").length,
    accessed: items.filter(f => f.accessStatus === "accessed").length,
    noAccessYet: items.filter(f => f.accessStatus === "no_access").length
  };
}

return [
  {
    json: {
      toolName: "metlo",
      target: fallbackTarget,
      status: "completed",
      findings,
      summary: buildSummary(findings),
      meta: {
        tool: "metlo",
        targetName,
        scanJobId,
        backendUrl: metloBackendUrl,
        targetHost,
        endpointCount: uniqueEndpoints.length,
        catalogEndpointCount: uniqueCatalogEndpoints.length,
        rawEndpointCount: rawEndpoints.length,
        alertCount: alerts.length,
        endpointNodeItems: endpointItems.length,
        summaryNodeItems: summaryItems.length,
        catalogNodeItems: catalogItems.length
      }
    }
  }
];

const input = $input.first().json || {};

const baseUrl = String(input.target || "").replace(/\/+$/, "");

if (!baseUrl || baseUrl === "N/A") {
